def count_Pairs(arr, n):
    cnt = 0
    used = set()
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] != arr[j]:
                pair = tuple(sorted((arr[i], arr[j])))
                if pair not in used:
                    cnt += 1
                    used.add(pair)
    return cnt

